export class ErasureRepository {
  async createOrFind(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureRequestRow | undefined> {
    return await transaction(async (client) => {
      await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`erasure:${merchantId}:${idempotencyKey}`]);
      await client.query(`SELECT pg_advisory_xact_lock(hashtext($1))`, [`erasure:${merchantId}:${customerId}`]);

      const keyed = await client.query<ErasureRequestRow & { requested_customer_id: string }>(
        `SELECT *,customer_id requested_customer_id FROM operations.customer_erasure_requests
         WHERE merchant_id=$1 AND idempotency_key=$2`,
        [merchantId, idempotencyKey],
      );
      if (keyed.rows[0]) {
        if (keyed.rows[0].requested_customer_id !== customerId) {
          throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
        }
        return keyed.rows[0];
      }

      const existing = await client.query<ErasureRequestRow>(
        `SELECT * FROM operations.customer_erasure_requests WHERE merchant_id=$1 AND customer_id=$2`,
        [merchantId, customerId],
      );
      if (existing.rows[0]) return existing.rows[0];

      const created = await client.query<ErasureRequestRow>(
        `INSERT INTO operations.customer_erasure_requests(merchant_id,customer_id,idempotency_key)
         SELECT $1,id,$3 FROM customers.customers WHERE merchant_id=$1 AND id=$2 AND status='active'
         RETURNING *`,
        [merchantId, customerId, idempotencyKey],
      );
      if (!created.rows[0]) return undefined;
      await client.query(
        `UPDATE customers.customers SET status='erasure_pending',updated_at=now(),version=version+1
         WHERE merchant_id=$1 AND id=$2`,
        [merchantId, customerId],
      );
      return created.rows[0];
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM operations.customer_erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async recoverExpired(): Promise<void> {
    await pool.query(
      `UPDATE operations.customer_erasure_requests
       SET status='failed',last_error='worker_lease_expired',next_attempt_at=now(),lease_expires_at=NULL,updated_at=now()
       WHERE status='processing' AND lease_expires_at<now()`,
    );
  }

  async claim(): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE operations.customer_erasure_requests
       SET status='processing',attempts=attempts+1,last_error=NULL,lease_expires_at=now()+interval '5 minutes',updated_at=now()
       WHERE id=(SELECT id FROM operations.customer_erasure_requests
         WHERE status IN ('pending','failed') AND next_attempt_at<=now()
         ORDER BY next_attempt_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
