    );
    return result.rows[0];
  }

  async context(request: ErasureRequestRow): Promise<ErasureContext> {
    const customer = await pool.query<{ email: string }>(
      `SELECT email FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [request.merchant_id, request.customer_id],
    );
    const manifests = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests WHERE merchant_id=$1 AND customer_id=$2`,
      [request.merchant_id, request.customer_id],
    );
    return { email: customer.rows[0]?.email ?? '', objectKeys: manifests.rows.map((row) => row.object_key) };
