import { logger } from '../../../packages/observability/src/logger.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureError,
  ErasureRepository,
  type ErasureContext,
  type ErasureRequestRow,
} from './erasure-repository.js';

export interface ErasureResponse {
  id: string;
  customerId: string;
  status: string;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function erasureResponse(row: ErasureRequestRow): ErasureResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at?.toISOString() ?? null,
    lastError: row.last_error,
  };
}

export class ErasureService {
  private readonly redis = new Redis(config().REDIS_URL, { lazyConnect: true });

  constructor(private readonly repository = new ErasureRepository()) {}

  async create(merchantId: string, customerId: string, idempotencyKey: string): Promise<ErasureResponse | undefined> {
    const request = await this.repository.createOrFind(merchantId, customerId, idempotencyKey);
    return request ? erasureResponse(request) : undefined;
  }

  async find(merchantId: string, requestId: string): Promise<ErasureResponse | undefined> {
    const request = await this.repository.find(merchantId, requestId);
    return request ? erasureResponse(request) : undefined;
  }

  async run(signal: AbortSignal): Promise<void> {
    let lastRecovery = 0;
    while (!signal.aborted) {
      try {
        if (Date.now() - lastRecovery > 30_000) {
          await this.repository.recoverExpired();
          lastRecovery = Date.now();
        }
        const request = await this.repository.claim();
        if (!request) {
          await new Promise((resolve) => setTimeout(resolve, 250));
          continue;
        }
        await this.process(request);
      } catch (error) {
        logger.error({ error }, 'customer erasure worker failed');
        await new Promise((resolve) => setTimeout(resolve, 1_000));
      }
    }
    if (this.redis.status !== 'wait') await this.redis.quit();
  }

  private async process(request: ErasureRequestRow): Promise<void> {
    try {
      const context = await this.repository.context(request);
      await this.deleteExternalReplicas(request, context);
      await this.repository.scrub(request);
      await this.deleteExternalReplicas(request, context);
      await this.repository.complete(request.id);
    } catch (error) {
      logger.warn({ error, erasureRequestId: request.id }, 'customer erasure attempt failed');
      await this.repository.fail(request.id, error);
    }
  }

  private async deleteExternalReplicas(request: ErasureRequestRow, context: ErasureContext): Promise<void> {
    try {
      if (context.objectKeys.length) await objectStore.removeObjects(DOCUMENT_BUCKET, context.objectKeys);
      await searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${request.merchant_id}:${request.customer_id}`,
        refresh: true,
        ignore: [404],
      });
      if (this.redis.status === 'wait') await this.redis.connect();
      const cacheKey = `merchant:${request.merchant_id}:customer:${request.customer_id}`;
      await this.redis.del(cacheKey, `${cacheKey}:activity`);
      if (context.email && !context.email.endsWith('@deleted.invalid')) await this.deleteMailpitMessages(context.email);
    } catch (error) {
      throw new ErasureError('external_cleanup_failed', error);
    }
  }

  private async deleteMailpitMessages(email: string): Promise<void> {
    const search = new URL('/api/v1/search', config().MAILPIT_API_URL);
    search.searchParams.set('query', `to:"${email.replaceAll('"', '')}"`);
    const result = await fetch(search, { signal: AbortSignal.timeout(5_000) });
    if (!result.ok) throw new Error(`mail search returned ${result.status}`);
    const payload = await result.json() as { messages?: { ID?: string; id?: string }[] };
    const ids = (payload.messages ?? []).map((message) => message.ID ?? message.id).filter((id): id is string => Boolean(id));
    if (!ids.length) return;
    const response = await fetch(new URL('/api/v1/messages', config().MAILPIT_API_URL), {
      method: 'DELETE',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ IDs: ids }),
      signal: AbortSignal.timeout(5_000),
    });
    if (!response.ok) throw new Error(`mail deletion returned ${response.status}`);
  }
}
